SELECT h.hk_cbs_jeugdzorg AS cbs_jeugdzorg_hk, h.vorm_code, h.wijk_code, h.periode_code, s.jongeren_totaal, s.trajecten_totaal, s.gemeente_naam, s.regio_type, s.load_date AS valid_from, coalesce(s.load_end_date, timestamp'9999-12-31 23:59:59') AS valid_to, s.is_current, s.record_source FROM {processing}.raw_vault.hub_cbs_jeugdzorg h JOIN {processing}.raw_vault.sat_cbs_jeugdzorg s ON s.hk_cbs_jeugdzorg = h.hk_cbs_jeugdzorg
